 function updateRankingSeason(){const info=rankingSeason(),opt=$('#wOfficialSeasonOption'),note=$('#wRankingSeasonInfo');if(opt)opt.textContent=`GARE VALIDE ALLA CLASSIFICA DELLA STAGIONE ${info.label}`;if(note)note.textContent=info.inferred?`Stagione ricavata automaticamente dalla data: ${info.label}.`:`Stagione della data evento: ${info.label}.`;return info}
