 function collect(){const rmode=rankingMode(),sinfo=rankingSeason();return {id:eventId,name:txt('#wName'),subtitle:txt('#wSubtitle'),start_date:val('#wStart'),end_date:val('#wEnd'),location:txt('#wLocation'),start_time:val('#wStartTime'),address:txt('#wAddress'),maps_url:txt('#wMaps'),parking_info:txt('#wParking'),accessibility_info:txt('#wAccessibility'),organizer_id:$('#wOrganizer').value,phone:txt('#wPhone'),email:txt('#wEmail'),whatsapp_url:txt('#wWhatsapp'),hospitality_info:txt('#wHospitality'),description_html:ATContent.sanitizeRichHtml($('#wDescription').innerHTML),judge_id:$('#wJudge').value,security_pin:txt('#wPin'),competition_mode:competitionMode(),race_operator_policy:'SINGLE_WRITER',stages:currentStages(),stage_config:stageConfig(),stage_config_confirmed:$('#wStageConfirmed').checked,entry_fee:txt('#wEntryFee')===''?null:Number(val('#wEntryFee')),two_day_fee:txt('#wTwoDayFee')===''?null:Number(val('#wTwoDayFee')),pricing_model:'BY_DAYS_PACKAGE',recall_cost_status:$('#wRecallStatus').value,recall_cost:txt('#wRecallCost')===''?null:Number(val('#wRecallCost')),max_pairs:$('#wUnlimitedPairs').checked?null:(txt('#wMaxPairs')===''?null:Number(val('#wMaxPairs'))),unlimited_pairs:$('#wUnlimitedPairs').checked,participation_rules:{mode:participationMode(),allowed_center_ids:participationMode()==='SELECTED_CENTERS'?selectedParticipationCenters():[],membership_season_id:P.season?.id||sinfo.id||null},ranking_mode:rmode,ranking_season_id:rmode==='OFFICIAL'?sinfo.id:null,ranking_season_label:rmode==='OFFICIAL'?sinfo.label:null,official_ranking:rmode==='OFFICIAL',early_discount_amount:txt('#wDiscount')===''?null:Number(val('#wDiscount')),early_discount_deadline:val('#wDiscountDeadline'),prereg_enabled:$('#wPreregEnabled').value==='true',prereg_email:txt('#wPreregEmail'),prereg_open_date:val('#wPreregOpen'),prereg_close_date:val('#wPreregClose'),prereg_max:$('#wUnlimitedPairs').checked?null:(txt('#wPreregMax')===''?null:Number(val('#wPreregMax'))),prereg_auto_email:$('#wPreregAutoEmail').value==='true',prereg_email_verified_required:true,prereg_note:txt('#wPreregNote'),prizes:txt('#wPrizes'),participant_gift:txt('#wGift'),awards_date:val('#wAwardsDate'),awards_time:val('#wAwardsTime'),awards_venue:txt('#wAwardsVenue'),awards_address:txt('#wAwardsAddress'),awards_maps_url:txt('#wAwardsMaps'),awards_link:txt('#wAwardsLink'),awards_notes:txt('#wAwardsNotes'),awards_datetime:val('#wAwardsDate')+(val('#wAwardsTime')?'T'+val('#wAwardsTime'):''),break_time:txt('#wBreak'),aperitivo_time:txt('#wAperitivo'),review_acknowledged:$('#wReviewConfirmed').checked,event_days:collectDays(),updated_at:new Date().toISOString()}}
 function completeness(d){const keys=['name','start_date','location','address','organizer_id','judge_id','security_pin','entry_fee','prizes'];if(!d.unlimited_pairs)keys.push('max_pairs');const filled=keys.filter(k=>(k==='security_pin'&&pinConfigured())||(d[k]!==null&&String(d[k]??'').trim()!=='')).length;return Math.round((filled/keys.length)*100)}
 function updateMeter(){const d=collect(),pct=completeness(d);$('#completionText').textContent=`${pct}% completo`;$('#completionBar').style.width=pct+'%';$('#draftStatus').textContent=`Bozza aggiornata ${new Date().toLocaleTimeString('it-IT')}`}
 function saveLocal(){draft=collect();if(window.ATDataAPI?.isOnline?.()){updateMeter();if(step===5)renderReview();return;}A=ATStore.admin();A.event_drafts=A.event_drafts||{};A.event_drafts[eventId||'NEW']=draft;ATStore.saveAdmin(A);updateMeter();if(step===5)renderReview()}
 document.querySelectorAll('input,select,textarea').forEach(x=>x.addEventListener('change',saveLocal));$('#wDescription').addEventListener('input',saveLocal);document.querySelectorAll('[data-cmd]').forEach(b=>b.onclick=()=>{document.execCommand(b.dataset.cmd,false,null);$('#wDescription').focus();saveLocal()});
 function showStep(n){step=Math.max(0,Math.min(5,n));document.querySelectorAll('.wizard-page').forEach(x=>x.classList.toggle('active',Number(x.dataset.page)===step));document.querySelectorAll('.wizard-step').forEach(x=>x.classList.toggle('active',Number(x.dataset.step)===step));$('#prevWizard').disabled=step===0;$('#nextWizard').style.visibility=step===5?'hidden':'visible';if(step===5)renderReview();window.scrollTo({top:document.querySelector('.wizard-steps').offsetTop-90,behavior:'smooth'})}
 $('#prevWizard').onclick=()=>showStep(step-1);$('#nextWizard').onclick=()=>showStep(step+1);document.querySelectorAll('.wizard-step').forEach(x=>x.onclick=()=>showStep(Number(x.dataset.step)));
 function reviewState(){const d=collect(),missing=[],warnings=[],ok=[];const req=[[d.name,'Nome evento'],[d.start_date,'Data evento'],[d.location,'Luogo'],[d.address,'Indirizzo/punto'],[d.organizer_id||txt('#wOrgName'),'Centro organizzatore'],[d.judge_id,'Giudice'],[d.security_pin||pinConfigured(),'PIN evento']];req.forEach(([v,l])=>(v?ok:missing).push(l));if(d.entry_fee===null)warnings.push('Quota una giornata DA DEFINIRE');else ok.push(`Quota una giornata € ${d.entry_fee.toFixed(2)}`);if(d.pricing_model==='BY_DAYS_PACKAGE'&&d.event_days?.length>1){if(d.two_day_fee===null)warnings.push('Quota pacchetto due giornate DA DEFINIRE');else ok.push(`Pacchetto due giornate € ${d.two_day_fee.toFixed(2)}`)}if(d.unlimited_pairs)ok.push('Partecipanti: nessun limite massimo');else if(d.max_pairs===null)warnings.push('Numero massimo binomi DA DEFINIRE');else ok.push(`Capienza ${d.max_pairs} binomi`);ok.push(d.competition_mode==='INDEPENDENT_DAYS'?'Formato: gare indipendenti per giornata':'Formato: gara unica distribuita su più giornate');if(!d.ranking_mode)warnings.push('Validità sportiva evento DA DEFINIRE');else if(d.ranking_mode==='OFFICIAL'){const si=rankingSeason();ok.push(`Evento UFFICIALE · stagione ${d.ranking_season_label||si.label||'DA DEFINIRE'}`);if(!si.inConfiguredSeason)warnings.push(`La stagione ${si.label} è ricavata dalla data ma non è configurata/archiviata nel gestionale: i punti resteranno in attesa finché la stagione non sarà configurata.`)}else if(d.ranking_mode==='AMATEUR')ok.push('Evento AMATORIALE · nessun punto stagionale');else ok.push('SIMULAZIONE / DEMO · classifiche ufficiali non modificate');if(d.recall_cost_status!=='DEFINITO')warnings.push('Costo Recall DA DEFINIRE');else if(d.recall_cost===null)warnings.push('Costo Recall marcato DEFINITO ma importo vuoto');else ok.push(`Costo Recall base € ${d.recall_cost.toFixed(2)} · matrice per prova/TPS configurabile`);if(!d.stage_config_confirmed)warnings.push('Prove/TPS NON ancora confermati');else ok.push('Prove/TPS confermati');const pr=d.participation_rules||{mode:'OPEN_TO_ALL',allowed_center_ids:[]};if(pr.mode==='OPEN_TO_ALL')ok.push('Partecipazione: APERTO A TUTTI');else if(pr.mode==='AQUATRAIL_MEMBERS_ONLY')ok.push('Partecipazione: RISERVATO AI TESSERATI AQUA TRAIL');else if(pr.mode==='SELECTED_CENTERS'){if(!(pr.allowed_center_ids||[]).length)warnings.push('Partecipazione: evento riservato ma nessun Centro selezionato');else ok.push('Partecipazione: '+participationCenterNames(pr.allowed_center_ids).join(' · '))}if(d.prereg_enabled&&!d.prereg_email)warnings.push('Preregistrazioni abilitate ma email ricezione NON configurata');else if(d.prereg_enabled)ok.push(`Preregistrazioni online abilitate → casella riservata configurata`);if(d.prereg_enabled&&!d.prereg_close_date)warnings.push('Data chiusura preregistrazioni non indicata');if(d.prereg_enabled&&d.prereg_open_date&&d.prereg_close_date&&d.prereg_close_date<d.prereg_open_date)warnings.push('La chiusura preregistrazioni precede la data di apertura');if(!d.awards_date)warnings.push('Data premiazione non indicata');if(d.participant_gift)ok.push('Omaggio partecipanti separato dai premi');const dayCheck=dayAssignmentState(d.event_days,d.stages);if(dayCheck.ok)ok.push(`Giornate configurate: ${d.event_days.length}`);else warnings.push(...dayCheck.errors.map(x=>'Giornate: '+x));warnings.push(...dayCheck.warnings.map(x=>'Giornate: '+x));const currentEvent=eventId?(P.events||[]).find(x=>x.id===eventId):null;if(currentEvent?.program_pdf&&!docDelete.PROGRAM)ok.push('PDF Programma completo disponibile');if(currentEvent?.menu_pdf&&!docDelete.MENU)ok.push('PDF Menu / Cosa ordinare disponibile');return {d,missing,warnings,ok}}
 function renderReview(){const r=reviewState(),org=organizerById(r.d.organizer_id);$('#reviewSummary').innerHTML=`<div class="notice ${r.missing.length?'warn':'ok'}"><strong>Dati principali</strong><br>${r.missing.length?'⚠ Mancano: '+r.missing.join(' · '):'✓ Dati principali presenti'}</div><div class="notice ${r.warnings.length?'warn':'ok'}"><strong>Decisioni / warning</strong><br>${r.warnings.length?r.warnings.map(x=>'• '+x).join('<br>'):'✓ Nessun valore decisionale lasciato implicito'}</div><div class="notice info"><strong>Riepilogo</strong><br>Evento: ${r.d.name||'—'}<br>Data: ${r.d.start_date||'—'}${r.d.end_date&&r.d.end_date!==r.d.start_date?' → '+r.d.end_date:''}<br>Luogo: ${r.d.location||'—'}<br>Centro organizzatore: ${org?.name||txt('#wOrgName')||r.d.organizer_id||'—'}<br>Chi può partecipare: ${r.d.participation_rules?.mode==='OPEN_TO_ALL'?'APERTO A TUTTI':r.d.participation_rules?.mode==='AQUATRAIL_MEMBERS_ONLY'?'TESSERATI AQUA TRAIL':participationCenterNames(r.d.participation_rules?.allowed_center_ids||[]).join(' · ')||'CENTRI NON SELEZIONATI'}<br>Giudice: ${(P.judges||[]).find(j=>j.id===r.d.judge_id)?.name||'—'}<br>Prove: ${r.d.stages.join(' · ')||'—'}<br>Giornate: ${(r.d.event_days||[]).map(d=>`${escHtml(d.label)} [${escHtml(d.date||'data?')}] → ${escHtml((d.stages||[]).join(' · ')||'nessuna prova')}`).join('<br>')||'—'}<br>${r.ok.map(x=>'✓ '+x).join('<br>')}</div>`}

 async function prepareOnlineImage(file){
   if(!/^image\/(jpeg|png|webp)$/.test(file.type)||typeof createImageBitmap!=='function')return file;
   let bitmap;try{bitmap=await createImageBitmap(file);const scale=Math.min(1,1200/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));const context=canvas.getContext('2d');if(!context)return file;context.drawImage(bitmap,0,0,canvas.width,canvas.height);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/webp',0.82));if(!blob||blob.type!=='image/webp'||blob.size>=file.size)return file;return new File([blob],file.name.replace(/\.[^.]+$/,'')+'.webp',{type:'image/webp'});}catch(_){return file;}finally{bitmap?.close?.();}
 }
 async function uploadOnlineAssets(id){
   const uploads=[['#wPoster','POSTER'],['#wProgramImage','PROGRAM_IMAGE'],['#wMenuImage','MENU_IMAGE'],['#wProgramPdf','PROGRAM_PDF'],['#wMenuPdf','MENU_PDF']].map(([selector,type])=>({input:$(selector),type}));
   document.querySelectorAll('.wizard-day-card').forEach(card=>uploads.push({input:card.querySelector('.wDayProgramPdf'),type:'DAY_PROGRAM_PDF',day_id:card.dataset.dayId}));
   for(const item of uploads){const original=item.input?.files?.[0];if(!original)continue;const file=item.type.endsWith('_IMAGE')||item.type==='POSTER'?await prepareOnlineImage(original):original;if(file.size>5*1024*1024)throw Error('Il file '+file.name+' supera il limite di 5 MB.');
     const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=()=>reject(Error('Impossibile leggere '+file.name));reader.readAsDataURL(file)});
     $('#publishMsg').textContent='Caricamento allegato: '+file.name+'…';
     try{await ATDataAPI.request('event_media_upload',{event_id:id,day_id:item.day_id||'',type:item.type,name:file.name,mime:file.type,base64:data});item.input.value='';}
     catch(e){throw Error('L’evento è stato mantenuto, ma l’allegato '+file.name+' non è stato caricato: '+String(e?.message||e));}
   }
 }
 async function saveOnlineDraft(){
   const buttons=['#saveDraft','#previewDraft','#publishDraft'].map(x=>$(x));
   try{
     const session=ATStore.session(),role=String(session?.role||'');if(!['ADMIN1','ADMIN2','SUPERADMIN'].includes(role))throw Error('La creazione di eventi è riservata agli amministratori.');if(session?.read_only)throw Error('Questo ambiente è in sola lettura.');
     if(!guardClosedEdit('salvare modifiche'))return null;
     const published=existingEvent();
     if(published?.published===true){
       const pin=txt('#wPin'),hasFiles=[...document.querySelectorAll('input[type="file"]')].some(input=>input.files?.length);
       if(pin&&!/^\d{4}$/.test(pin))throw Error('Il PIN evento deve contenere 4 cifre.');
       if(!pin&&!hasFiles)throw Error('Inserisci un nuovo PIN o seleziona un allegato da sostituire. La modifica degli altri dati non è ancora disponibile qui.');
       buttons.forEach(b=>{if(b)b.disabled=true});
       if(pin){$('#publishMsg').textContent='Salvataggio PIN in corso…';await ATDataAPI.command('safety_mutation',{operation:'set_pin',event_id:eventId,secret:pin});const verification=await ATDataAPI.verifySecret('PIN',eventId,pin);if(verification?.verified!==true)throw Error('Il PIN è stato inviato ma non è stato possibile confermarlo.');$('#wPin').value='';}
       await uploadOnlineAssets(eventId);await ATDataAPI.staffBootstrap();P=ATEventOnlineMapping.hydrate(ATStore.public());A=ATStore.admin();
       const saved=(P.events||[]).find(x=>String(x.id)===String(eventId));if(!saved||saved.published!==true)throw Error('Allegati caricati, ma non è stato possibile verificare lo stato dell’evento.');
       $('#publishMsg').textContent='Stato: PUBBLICATO · '+(pin?'PIN aggiornato'+(hasFiles?' e allegati aggiornati':''):'allegati aggiornati')+'. Gli altri dati non sono stati modificati.';$('#wizardTitle').textContent=saved.name+' · PUBBLICATO';updateMeter();renderReview();return saved;
     }
     const d=collect();if(!d.name)throw Error('Inserisci il nome dell’evento.');const pin=String(d.security_pin||'');if(pin&&!/^\d{4}$/.test(pin))throw Error('Il PIN evento deve contenere 4 cifre.');
     if(txt('#wOrgName')&&!d.organizer_id)throw Error('Seleziona un centro già esistente prima di salvare.');
     if(!validateObstacleVariations(d.stage_config))return null;
     const tc=validStageTimes(d.stage_config);if(!tc.ok)throw Error('Controlla i tempi delle prove: '+(tc.reason||tc.stage||'valori non validi'));
     if(Object.values(docDelete).some(Boolean)||document.querySelector('[data-delete-pdf="1"]'))throw Error('La rimozione degli allegati non è ancora disponibile online.');
     const id=eventId||('DK-'+Date.now()+'-'+Math.random().toString(36).slice(2,8));
     d.id=id;d.status='BOZZA';d.published=false;
     const current=ATStore.public();const existing=(current.events||[]).find(x=>String(x.id)===String(id));
     if(existing&&existing.published)throw Error('La modifica di un evento già pubblicato non è disponibile in questa schermata online.');
     const operations=ATEventOnlineMapping.operations(d,id,current);
     buttons.forEach(b=>{if(b)b.disabled=true});$('#publishMsg').textContent='Salvataggio in corso…';
     eventId=id;
     if(operations.length===1)await ATDataAPI.command(operations[0].name,operations[0].payload);
     else await ATDataAPI.command('atomic_batch',{operations});
     if(pin){try{await ATDataAPI.command('safety_mutation',{operation:'set_pin',event_id:id,secret:pin});}catch(e){throw Error('La bozza è stata salvata, ma il PIN non è stato confermato. Ricarica e verifica prima di riprovare.');}}
     try{await ATDataAPI.staffBootstrap()}catch(e){throw Error('Il server ha accettato il salvataggio, ma non è stato possibile verificarlo. Ricarica la pagina prima di riprovare.');}
     await uploadOnlineAssets(id);
     if(window.ATDataAPI?.isOnline?.())await ATDataAPI.staffBootstrap();
     P=ATEventOnlineMapping.hydrate(ATStore.public());A=ATStore.admin();
     const saved=(P.events||[]).find(x=>String(x.id)===id);
     if(!saved||String(saved.name)!==String(d.name))throw Error('Il server ha risposto, ma la bozza non è stata confermata. Ricarica e verifica prima di riprovare.');
     const savedDays=(P.event_days||[]).filter(x=>String(x.event_id)===id),savedStages=(P.stage_config||[]).filter(x=>String(x.event_id)===id);
     if((d.event_days||[]).some(day=>!savedDays.some(x=>String(x.id)===String(day.id)))||(d.stage_config||[]).some(stage=>!savedStages.some(x=>String(x.day_id||'')===String(stage.day_id||'')&&String(x.competition_id||'')===String(stage.competition_id||'')&&String(x.stage)===String(stage.stage))))throw Error('Evento salvato, ma giornate o prove non sono state confermate. Ricarica e verifica prima di riprovare.');
     if(pin)$('#wPin').value='';updateMeter();renderReview();
     $('#publishMsg').textContent='Stato: BOZZA PRIVATA · salvataggio confermato';$('#wizardTitle').textContent=saved.name+' · BOZZA';
     return saved;
   }catch(e){$('#publishMsg').textContent='Salvataggio non completato · '+String(e?.message||e);alert(String(e?.message||e));return null;}
   finally{buttons.forEach(b=>{if(b)b.disabled=false});}
 }
 async function publishOnlineEvent(){
   let publishSent=false;
   const buttons=['#saveDraft','#previewDraft','#publishDraft'].map(x=>$(x));
   try{
     if(existingEvent()?.published===true){await saveOnlineDraft();return;}
     const review=reviewState(),d=review.d;
     if(review.missing.length)throw Error('Completa i dati principali: '+review.missing.join(', ')+'.');
     if(!d.ranking_mode)throw Error('Scegli la validità sportiva dell’evento.');
     if(!(d.stages||[]).length)throw Error('Seleziona almeno una prova per l’evento.');
     if(!d.stage_config_confirmed||!d.review_acknowledged)throw Error('Conferma le prove e il riepilogo finale.');
     const dayCheck=dayAssignmentState(d.event_days,d.stages);if(!dayCheck.ok)throw Error('Controlla le giornate: '+dayCheck.errors.join(', '));
     const saved=await saveOnlineDraft();if(!saved)return;
     buttons.forEach(b=>{if(b)b.disabled=true});
     const integrity=publicationIntegrity(saved);if(!integrity.ok)throw Error('Controlla i dati dell’evento: '+integrity.errors.join(', '));
     if(!saved.updated_at)throw Error('Versione evento non disponibile. Ricarica prima di pubblicare.');
     $('#publishMsg').textContent='Pubblicazione in corso…';
     publishSent=true;
     await ATDataAPI.command('event_mutation',{operation:'update',table:'EVENTI',id:eventId,event_id:eventId,expected_updated_at:String(saved.updated_at),changes:{STATUS:'PUBBLICATO',PUBLISHED:true,PUBLISHED_AT:new Date().toISOString()}});
     await ATDataAPI.staffBootstrap();
     const staffEvent=(ATStore.public().events||[]).find(x=>String(x.id)===String(eventId));
     const result=await ATDataAPI.request('public_bundle',{page:'evento.html',event_id:eventId,view:'public'});
     const publicEvent=(result.public_data?.events||[]).find(x=>String(x.id)===String(eventId));
     if(!staffEvent||staffEvent.published!==true||!publicEvent||publicEvent.published!==true)throw Error('La pubblicazione non è stata confermata.');
     $('#publishMsg').textContent='Stato: PUBBLICATO · confermato sul sito';$('#wizardTitle').textContent=staffEvent.name+' · PUBBLICATO';
   }catch(e){const message=publishSent?'Non è stato possibile confermare la pubblicazione. Ricarica e verifica lo stato dell’evento prima di riprovare.':String(e?.message||e);$('#publishMsg').textContent=message;alert(message);}
   finally{buttons.forEach(b=>{if(b)b.disabled=false});}
 }
